import { loadFont as loadCond } from "@remotion/google-fonts/BarlowCondensed";
import { loadFont as loadBody } from "@remotion/google-fonts/Barlow";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// DECORE ARTES (pedido) · ÁLVARO SOLUÇÕES DIGITAIS. Motion vertical de venda do cardápio digital com pedido no WhatsApp.
// Jeito: motion (só logos e 3 flyers de referência). As telas do celular são prints reais do cardápio-modelo da Casa das Massas.
// Identidade dos flyers e do Instagram: preto, branco e cromado, letra condensada itálica pesada, faixa branca inclinada.
// O laranja só aparece dentro das telas da pizzaria e o verde só no WhatsApp.
// Privacidade: nome, telefone e rua do pedido de exemplo vão desfocados.
// Tempos = tempos da locução v1 (src/voz-v1.mp3, 37,5 s); o vídeo tem LEAD de entrada.
// v2 (revisão da Nina): 6 pausas da voz cortadas (voz-v2-sem-pausas.wav). CUTS = trechos da voz v1 que saíram; o tempo do vídeo
// é convertido no tempo antigo por toOld(), então as animações continuam escritas no tempo da v1.
// Área segura: texto e celular em x 120–960, y 250–1480.
// v3 (correção 2 da Nina): títulos maiores com a palavra-chave numa caixa (branca no escuro, preta no claro), celular a ~65% da
// largura numa janela de 840 × 930 (y 530–1460), gancho somando as linhas, cartões de dor riscados, zoom por linha no WhatsApp,
// fim com "Álvaro Soluções Digitais" + "Chama no Instagram" + @.

const { fontFamily: C } = loadCond("italic", { weights: ["700", "800", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: B } = loadBody("normal", { weights: ["500", "600", "700"], subsets: ["latin", "latin-ext"] });

export const DA_FPS = 30;
const LEAD = 0.2;
// v5: voz Roger (src/voz-v5-roger-sem-pausas.wav, silêncios encurtados). VOZ5 = [tempo da voz nova, tempo da voz v1], palavra por
// palavra; as animações continuam escritas no tempo da v1 e toOld() converte. Antes da primeira e depois da última palavra, ritmo 1:1.
const VOZ5: [number, number][] = [[0.0, 0.0], [0.34, 0.32], [0.7, 0.78], [0.9, 0.92], [1.93, 2.67], [2.16, 2.82], [3.33, 4.43], [3.58, 4.68], [3.78, 4.9], [4.42, 5.7], [4.8, 6.06], [5.02, 6.24], [5.86, 7.22], [6.08, 7.44], [6.46, 7.8], [6.58, 7.92], [7.21, 9.07], [7.45, 9.24], [7.87, 9.74], [8.31, 10.12], [8.57, 10.32], [8.97, 10.58], [9.51, 11.1], [10.41, 12.12], [10.59, 12.2], [10.97, 12.52], [11.31, 12.94], [11.61, 13.22], [12.51, 14.16], [12.59, 14.26], [13.39, 15.1], [13.45, 15.18], [14.25, 15.96], [14.43, 16.18], [14.89, 16.62], [15.25, 16.9], [15.39, 17.0], [16.11, 18.03], [16.45, 18.4], [16.55, 18.48], [16.99, 18.92], [17.35, 19.4], [17.49, 19.52], [17.75, 19.78], [17.93, 19.94], [18.09, 20.08], [18.57, 20.62], [18.93, 21.0], [20.04, 22.25], [20.83, 23.1], [21.35, 23.62], [21.65, 24.1], [22.51, 25.26], [22.61, 25.34], [23.01, 25.78], [23.25, 26.08], [23.69, 26.56], [23.89, 26.74], [24.35, 27.66], [24.77, 27.84], [24.91, 27.94], [25.03, 28.14], [25.77, 28.92], [25.97, 29.22], [26.77, 30.3], [26.83, 30.38], [27.01, 30.5], [28.02, 32.14], [28.13, 32.22], [28.99, 33.06], [29.59, 33.64], [29.77, 34.02], [30.8, 35.41], [31.12, 35.86], [31.62, 36.08], [31.7, 36.14], [32.08, 36.42], [32.46, 36.98], [32.94, 37.4], [33.08, 37.5]];
const toOld = (n: number) => {
  if (n <= VOZ5[0][0]) return n;
  const L = VOZ5[VOZ5.length - 1];
  if (n >= L[0]) return L[1] + (n - L[0]);
  let i = 1;
  while (VOZ5[i][0] < n) i++;
  const [a0, b0] = VOZ5[i - 1], [a1, b1] = VOZ5[i];
  return b0 + ((n - a0) / (a1 - a0)) * (b1 - b0);
};
export const DA_FRAMES = Math.round(34.96 * DA_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const BACK = Easing.out(Easing.back(1.4));
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const bump = (t: number, a: number, d = 0.35) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI));

const BLACK = "#0A0A0B";
const WHITE = "#FFFFFF";
const GREY = "#8C8C92";
const SILVER_D = "linear-gradient(180deg, #3A3A3F 0%, #5C5C62 46%, #0A0A0B 52%, #2E2E33 100%)";
const SILVER = "linear-gradient(180deg, #FFFFFF 0%, #F1F1F3 40%, #CFCFD3 49%, #BFBFBF 52%, #DCDCDF 78%, #FFFFFF 100%)";
const ORANGE = "#D9480F";
const WA = "#25D366";
const img = (f: string) => staticFile(`decore-artes/${f}`);

// ───────── texto: sobe da linha (máscara) e fica parado; some inteiro no mesmo lugar ─────────
const Rise: React.FC<{ t: number; at: number; out?: number; size: number; silver?: boolean; color?: string; dark?: boolean; children: React.ReactNode }> = ({ t, at, out, size, silver, color = WHITE, dark, children }) => {
  const e = k(t, at, 0.42);
  const gone = out !== undefined && t >= out;
  return (
    <div style={{ overflow: "hidden", padding: `${size * 0.04}px ${size * 0.08}px ${size * 0.14}px`, margin: `-${size * 0.06}px 0 -${size * 0.16}px`, opacity: gone ? 0 : 1 }}>
      <div
        style={{
          fontFamily: C, fontStyle: "italic", fontWeight: 900, fontSize: size, lineHeight: 0.98, letterSpacing: "-0.01em", textTransform: "uppercase", whiteSpace: "nowrap",
          transform: `translateY(${((1 - e) * 150).toFixed(2)}%)`,
          ...(silver ? { background: dark ? SILVER_D : SILVER, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent" } : { color }),
        }}
      >
        {children}
      </div>
    </div>
  );
};
// palavra-chave numa caixa inclinada (a faixa dos flyers): branca com letra preta no escuro, preta com letra branca no claro
const Key: React.FC<{ t: number; at: number; size: number; inv?: boolean; children: React.ReactNode }> = ({ t, at, size, inv, children }) => {
  const e = k(t, at, 0.4);
  return (
    <div style={{ background: inv ? BLACK : WHITE, transform: "skewX(-12deg)", padding: `${size * 0.05}px ${size * 0.16}px ${size * 0.07}px`, clipPath: `inset(0 ${((1 - e) * 100).toFixed(2)}% 0 0)` }}>
      <div style={{ transform: "skewX(12deg)" }}>
        <Rise t={t} at={at + 0.05} size={size} color={inv ? WHITE : BLACK}>{children}</Rise>
      </div>
    </div>
  );
};
type W = [string, number, (boolean | "box")?];
const Line: React.FC<{ t: number; words: W[]; size: number; out?: number; color?: string; dark?: boolean }> = ({ t, words, size, out, color, dark }) => (
  <div style={{ display: "flex", justifyContent: "center", alignItems: "center", gap: size * 0.2 }}>
    {words.map(([w, at, s], i) =>
      s === "box" ? (
        <Key key={i} t={t} at={at} size={size} inv={dark}>{w}</Key>
      ) : (
        <Rise key={i} t={t} at={at} out={out} size={size} silver={s === true} color={color} dark={dark}>{w}</Rise>
      ),
    )}
  </div>
);
const Block: React.FC<{ top: number; children: React.ReactNode }> = ({ top, children }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap: 8 }}>{children}</div>
);
// faixa branca inclinada dos flyers, com texto preto
const Banner: React.FC<{ t: number; at: number; size: number; children: React.ReactNode }> = ({ t, at, size, children }) => {
  const e = k(t, at, 0.5);
  return (
    <div style={{ display: "inline-block", background: WHITE, transform: `skewX(-14deg)`, padding: `${size * 0.1}px ${size * 0.5}px ${size * 0.14}px`, clipPath: `inset(0 ${((1 - e) * 100).toFixed(2)}% 0 0)` }}>
      <div style={{ transform: "skewX(14deg)", fontFamily: C, fontStyle: "italic", fontWeight: 900, fontSize: size, lineHeight: 1, color: BLACK, textTransform: "uppercase", whiteSpace: "nowrap" }}>{children}</div>
    </div>
  );
};

// reflexo que atravessa o logo (máscara pelo próprio png)
const Shine: React.FC<{ t: number; src: string; at: number[]; alpha?: number }> = ({ t, src, at, alpha = 0.85 }) => {
  const a = at.find((x) => t >= x && t < x + 0.9);
  if (a === undefined) return null;
  const p = interpolate(t, [a, a + 0.9], [-25, 125], { ...cl, easing: INOUT });
  const m = { WebkitMaskImage: `url(${src})`, maskImage: `url(${src})`, WebkitMaskSize: "100% 100%", maskSize: "100% 100%" } as React.CSSProperties;
  return <div style={{ position: "absolute", inset: 0, ...m, background: `linear-gradient(110deg, transparent ${p - 14}%, rgba(255,255,255,${alpha}) ${p}%, transparent ${p + 14}%)` }} />;
};

// ───────── celular + câmera estilo Screen Studio ─────────
const PW = 600, PH = 1260, IN = 18, SW = PW - 2 * IN; // tela 564 de largura
const SS = SW / 1170; // escala dos prints (1170 de largura)
const sp = (x: number, y: number): [number, number] => [IN + x * SS, IN + y * SS]; // ponto do print → ponto no celular
const Phone: React.FC<{ children: React.ReactNode; bg?: string }> = ({ children, bg = "#FFF8EC" }) => (
  <div style={{ position: "relative", width: PW, height: PH, borderRadius: 92, background: "linear-gradient(135deg,#3a3a3e,#0d0d0f 40%,#2b2b2f 70%,#09090a)", boxShadow: "0 50px 120px rgba(0,0,0,0.7), inset 0 0 0 2px rgba(255,255,255,0.18)" }}>
    <div style={{ position: "absolute", left: IN, top: IN, width: SW, height: PH - 2 * IN, borderRadius: 76, overflow: "hidden", background: bg }}>{children}</div>
    <div style={{ position: "absolute", left: PW / 2 - 70, top: IN + 14, width: 140, height: 38, borderRadius: 20, background: "#000" }} />
  </div>
);
// janela do celular: 840 × 1000 dentro da área segura; zoom 1,1 = celular inteiro na janela
const WIN_W = 840, WIN_H = 930, WIN_TOP = 530, BASE = 1.17 / 1.1; // zoom 1,1 = celular com 702 px de largura (65%)
type Cam = [number, number, number, number]; // tempo, zoom, foco x, foco y (coordenadas do celular)
const camAt = (t: number, keys: Cam[]) => {
  let [, z, x, y] = keys[0];
  for (let i = 1; i < keys.length; i++) {
    const [ta, za, xa, ya] = keys[i - 1];
    const [tb, zb, xb, yb] = keys[i];
    if (t >= ta) {
      const p = io(t, ta, tb);
      z = za + (zb - za) * p; x = xa + (xb - xa) * p; y = ya + (yb - ya) * p;
    }
  }
  return { z, x, y };
};
const World: React.FC<{ t: number; keys: Cam[]; top: number; children: React.ReactNode; enter?: number }> = ({ t, keys, top, children, enter }) => {
  const { z, x, y } = camAt(t, keys);
  const e = enter === undefined ? 1 : k(t, enter, 0.7);
  const cx = PW / 2, cy = PH / 2;
  return (
    <div style={{ position: "absolute", left: 120, width: WIN_W, top, height: WIN_H, overflow: "hidden", borderRadius: 40 }}>
      <div style={{ position: "absolute", left: WIN_W / 2 - cx, top: WIN_H / 2 - cy, width: PW, height: PH, transformOrigin: `${cx}px ${cy}px`, transform: `translate(${((cx - x) * z * BASE).toFixed(1)}px, ${((cy - y) * z * BASE + (1 - e) * 900).toFixed(1)}px) scale(${(z * BASE).toFixed(4)}) rotate(${((1 - e) * 8).toFixed(2)}deg)` }}>
        {children}
      </div>
    </div>
  );
};
// cursor que anda com mola e aperta no clique
type Way = [number, number, number];
const Cursor: React.FC<{ t: number; path: Way[]; taps: number[]; from: number; to: number }> = ({ t, path, taps, from, to }) => {
  if (t < from || t > to) return null;
  let [, x, y] = path[0];
  for (let i = 1; i < path.length; i++) {
    const [ta, xa, ya] = path[i - 1];
    const [tb, xb, yb] = path[i];
    if (t >= ta) { const p = io(t, ta, tb); x = xa + (xb - xa) * p; y = ya + (yb - ya) * p; }
  }
  const tap = taps.reduce((m, a) => Math.max(m, bump(t, a, 0.22)), 0);
  const ring = taps.find((a) => t > a && t < a + 0.5);
  const o = Math.min(lin(t, from, from + 0.2), 1 - lin(t, to - 0.2, to));
  return (
    <div style={{ position: "absolute", left: x, top: y, opacity: o, zIndex: 9 }}>
      {ring !== undefined ? <div style={{ position: "absolute", left: -34, top: -34, width: 68, height: 68, borderRadius: 40, border: `4px solid ${ORANGE}`, opacity: 1 - lin(t, ring, ring + 0.5), transform: `scale(${(0.4 + lin(t, ring, ring + 0.5)).toFixed(3)})` }} /> : null}
      <svg width={46} height={56} viewBox="0 0 23 28" style={{ transform: `scale(${(1 - 0.18 * tap).toFixed(3)})`, transformOrigin: "2px 2px", filter: "drop-shadow(0 4px 6px rgba(0,0,0,0.35))" }}>
        <path d="M2 2 L2 22 L7.5 17 L11 25 L14.5 23.5 L11 15.8 L18.5 15.8 Z" fill="#111" stroke="#fff" strokeWidth={1.6} strokeLinejoin="round" />
      </svg>
    </div>
  );
};

