  );
};

// 2 · a bagunça: áudio, endereço pela metade, conta na mão
const RED = "#E5484D";
const Card: React.FC<{ t: number; at: number; strike: number; label: string; side?: number; children: React.ReactNode }> = ({ t, at, strike, label, side = 1, children }) => {
  const e = k(t, at, 0.55);
  const st = io(t, strike, strike + 0.25);
  const x = pop(t, strike + 0.1, 0.35);
  return (
    <div style={{ position: "relative", width: 920, height: 300, borderRadius: 40, background: "#161618", border: `2px solid ${st > 0.5 ? "#4A2226" : "#2A2A2E"}`, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 18, opacity: Math.min(1, e * 2), transform: `translateX(${((1 - e) * 420 * side).toFixed(1)}px) rotate(${((1 - e) * 6 * side).toFixed(2)}deg) scale(${(1 + 0.04 * bump(t, at + 0.35, 0.3)).toFixed(3)})`, filter: `blur(${((1 - e) * 10).toFixed(1)}px)` }}>
      <div style={{ height: 96, display: "flex", alignItems: "center", opacity: 0.75 }}>{children}</div>
