          <span style={{ fontFamily: B, fontWeight: 700, fontSize: 62, color: BLACK }}>@suamarca</span>
        </div>
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1290, display: "flex", justifyContent: "center", opacity: k(t, 36.8, 0.5) }}>
        <div style={{ fontFamily: B, fontWeight: 600, fontSize: 40, letterSpacing: "0.32em", color: "#CFCFD3" }}>CARDÁPIO DIGITAL</div>
      </div>
    </AbsoluteFill>
  );
};

// trocas variadas: círculo, faixa inclinada, subida, (inundação dentro da cena 5), descida, metades, diagonal, círculo
const SCENES: [number, React.FC<{ t: number }>, (p: number) => string][] = [
  [-9, S1, () => "none"],
  [T2, S2, (p) => `circle(${(p * 125).toFixed(1)}% at 50% 70%)`],
  [T3, S3, (p) => `polygon(0 0, ${(p * 170).toFixed(1)}% 0, ${(p * 170 - 60).toFixed(1)}% 100%, 0 100%)`],
  [T4, S4, (p) => `inset(${((1 - p) * 100).toFixed(2)}% 0 0 0)`],
  [T5, S5, (p) => `inset(0 ${((1 - p) * 100).toFixed(2)}% 0 0)`],
  [T6, S6, (p) => `inset(0 0 ${((1 - p) * 100).toFixed(2)}% 0)`],
  [T7, S7, (p) => `inset(0 ${((1 - p) * 50).toFixed(2)}% 0 ${((1 - p) * 50).toFixed(2)}%)`],
  [T8, S8, (p) => `polygon(${(100 - p * 170).toFixed(1)}% 0, 100% 0, 100% 100%, ${(160 - p * 170).toFixed(1)}% 100%)`],
  [T9, S9, (p) => `circle(${(p * 125).toFixed(1)}% at 50% 40%)`],
];

// faixa inclinada (as setas dos flyers) que atravessa a tela na troca de cena e inverte o que está embaixo
const Slash: React.FC<{ t: number; at: number; dir: number }> = ({ t, at, dir }) => {
  if (t < at - 0.12 || t > at + 0.5) return null;
  const p = interpolate(t, [at - 0.12, at + 0.5], [0, 1], { ...cl, easing: Easing.bezier(0.5, 0, 0.3, 1) });
  const x = dir > 0 ? -900 + p * 2900 : 1980 - p * 2900;
  return (
    <AbsoluteFill style={{ mixBlendMode: "difference", pointerEvents: "none" }}>
      <div style={{ position: "absolute", top: -300, height: 2520, left: x, width: 230, background: WHITE, transform: "skewX(-22deg)" }} />
      <div style={{ position: "absolute", top: -300, height: 2520, left: x - dir * 110, width: 16, background: WHITE, transform: "skewX(-22deg)" }} />
    </AbsoluteFill>
  );
};

export const DecoreArtes: React.FC = () => {
  const t = toOld(useCurrentFrame() / DA_FPS - LEAD);
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      {SCENES.map(([at, S, clip], i) => {
        const end = i + 1 < SCENES.length ? SCENES[i + 1][0] + 0.45 : 1e9;
        if (t < at || t >= end) return null;
        const p = i === 0 ? 1 : interpolate(t, [at, at + 0.42], [0, 1], { ...cl, easing: INOUT });
        return (
          <AbsoluteFill key={i} style={p < 1 ? { clipPath: clip(p) } : undefined}>
            {/* a cena entra já em movimento (empurrão curto) e recua quando a próxima chega */}
            <AbsoluteFill style={{ transform: `scale(${(0.93 + 0.07 * k(t, i === 0 ? -0.25 : at, 0.7) - 0.03 * Math.pow(lin(t, end - 0.7, end), 2)).toFixed(4)}) rotate(${((1 - k(t, i === 0 ? -0.25 : at, 0.7)) * (i % 2 ? 1.6 : -1.6)).toFixed(2)}deg)` }}>
              <S t={t} />
            </AbsoluteFill>
          </AbsoluteFill>
        );
      })}
      {SCENES.slice(1).map(([at], i) => <Slash key={i} t={t} at={at} dir={i % 2 ? -1 : 1} />)}
    </AbsoluteFill>
  );
};

